@Test
void updateJsonEnvBatch() throws Exception {
    long dataSourceEnvId = 10l;
    String fromSystem = "WTSS";
    String url = "/data-source-manager/env/json/batch?system=";
    List<DataSourceEnv> dataSourceEnvList = new ArrayList<>();
    DataSourceEnv dataSourceEnv = new DataSourceEnv();
    dataSourceEnv.setId(dataSourceEnvId);
    dataSourceEnvList.add(dataSourceEnv);
    StringWriter dsJsonWriter = new StringWriter();
    JsonUtils.jackson().writeValue(dsJsonWriter, dataSourceEnvList);
    MvcUtils mvcUtils = new MvcUtils(mockMvc);
    moduleUserUtils.when(() -> ModuleUserUtils.getOperationUser(isA(HttpServletRequest.class), isA(String.class))).thenReturn("testUser", "hadoop");
    Message mvcResult = mvcUtils.getMessage(mvcUtils.buildMvcResultPut(url + fromSystem, dsJsonWriter.toString()));
    assertTrue(MessageStatus.ERROR() == mvcResult.getStatus() && mvcResult.getMessage().contains("is not admin user"));
    fromSystem = "Qualitis";
    Mockito.when(dataSourceInfoService.getDataSourceEnv(dataSourceEnvId)).thenReturn(null).thenReturn(dataSourceEnv);
    mvcResult = mvcUtils.getMessage(mvcUtils.buildMvcResultPut(url + fromSystem, dsJsonWriter.toString()));
    assertTrue(MessageStatus.ERROR() == mvcResult.getStatus() && mvcResult.getMessage().contains("Fail to update data source environment"));
    mvcResult = mvcUtils.getMessage(mvcUtils.buildMvcResultPut(url, dsJsonWriter.toString()));
    assertTrue(MessageStatus.SUCCESS() == mvcResult.getStatus());
    List<Map<String, Object>> dataSourceEnvMap = (List<Map<String, Object>>) mvcResult.getData().get("envs");
    assertTrue(CollectionUtils.isNotEmpty(dataSourceEnvMap));
    assertEquals(10, dataSourceEnvMap.get(0).get("id"));
}

